   111    // parse one compound selector, which is basically
   112    // a list of simple selectors (directly adjacent)
   113    // lex them exactly (without skipping white-space)
   114    CompoundSelectorObj Parser::parseCompoundSelector()
   115    {
   116      // init an empty compound selector wrapper
   117      CompoundSelectorObj seq = SASS_MEMORY_NEW(CompoundSelector, pstate);
   118
   119      // skip initial white-space
   120      lex < block_comment >();
   121      advanceToNextToken();
   122
   123      if (lex< exactly<'&'> >(false))
   124      {
   125        // ToDo: check the conditions and try to simplify flag passing
   126        if (!allow_parent) error("Parent selectors aren't allowed here.");
   127        // Create and append a new parent selector object
   128        seq->hasRealParent(true);
   129      }
   130
   131      // parse list
   132      while (true)
   133      {
   134        // remove all block comments
   135        // leaves trailing white-space
   136        lex < block_comment >();
   137        // parse parent selector
   138        if (lex< exactly<'&'> >(false))
   139        {
   140          // parent selector only allowed at start
   141          // upcoming Sass may allow also trailing
   142          ParserState state(pstate);
   143          SimpleSelectorObj prev = (*seq)[seq->length()-1];
   144          std::string sel(prev->to_string({ NESTED, 5 }));
   145          std::string found("&");
   146          if (lex < identifier >()) { found += std::string(lexed); }
   147          // ToDo: parser should throw parser exceptions
   148          error("Invalid CSS after \"" + sel + "\": expected \"{\", was \"" + found + "\"\n\n"
   149            "\"" + found + "\" may only be used at the beginning of a compound selector.", state);
   150        }
   151        // parse functional
   152        else if (match < re_functional >())
   153          {
   154            seq->append(parse_simple_selector());
   155          }
   156
   157        // parse type selector
   158        else if (lex< re_type_selector >(false))
   159        {
   160          seq->append(SASS_MEMORY_NEW(Type_Selector, pstate, lexed));
   161        }
   162        // peek for abort conditions
   163        else if (peek< spaces >()) break;
   164        else if (peek< end_of_file >()) { break; }
   165        else if (peek_css < class_char < selector_combinator_ops > >()) break;
   166        else if (peek_css < class_char < complex_selector_delims > >()) break;
   167        // otherwise parse another simple selector
   168        else {
   169          SimpleSelectorObj sel = parse_simple_selector();
   170          if (!sel) return {};
   171          seq->append(sel);
   172        }
   173      }
   174      // EO while true
   175
   176      if (seq && !peek_css<alternatives<end_of_file,exactly<'{'>>>()) {
   177        seq->hasPostLineBreak(peek_newline());
   178      }
   179
   180      // We may have set hasRealParent
   181      if (seq && seq->empty() && !seq->hasRealParent()) return {};
   182
   183      return seq;
   184    }
